  fp_r.debugDisableShadows = false;
  try {
    await fpRenderPreview(tester, preview);
  } finally {
    fp_r.debugDisableShadows = shadowsDisabled;
  }
}

Future<void> fpRenderPreview(fp_t.WidgetTester tester, FpPreview preview) async {
